    var M = {"john":{"sw":"\"Yahweh ni mwenye neema\""},"mary":{"sw":"Haijulikani — \"mpendwa\", \"uchungu\", au \"mtoto aliyetamaniwa\""},"muhammad":{"sw":"\"Mwenye kusifiwa\", \"anayestahili sifa\""},"alexander":{"sw":"\"Mlinzi wa watu\" (aléxō \"kulinda\" + anḗr \"mtu\")"},"joseph":{"sw":"\"Ataongeza\" / \"Mungu na aongeze\""},"michael":{"sw":"\"Ni nani aliye kama Mungu?\""},"george":{"sw":"\"Mkulima, mlimaji wa ardhi\" (gē \"ardhi\" + ergon \"kazi\")"},"sophia":{"sw":"\"Hekima\""},"fatima":{"sw":"\"Yule anayeachisha kunyonya / anayejizuia\" (shina f-ṭ-m)"},"ali":{"sw":"\"Wa juu, mtukufu, aliyetukuka\" (shina ʿ-l-w)"},"krishna":{"sw":"\"Giza, nyeusi\" (kwa rangi ya ngozi ya buluu-nyeusi ya mungu)"},"rama":{"sw":"\"Wa kupendeza, wa kuvutia, wa kufurahisha\" (shina ram- \"kupendeza\")"},"david":{"sw":"\"Mpendwa\""},"daniel":{"sw":"\"Mungu ni hakimu wangu\" (dān \"kuhukumu\" + ʼēl \"Mungu\")"},"peter":{"sw":"\"Mwamba, jiwe\" — lililobuniwa na Yesu kutafsiri neno la Kiaramu Kēfā"},"paul":{"sw":"\"Mdogo, mnyenyekevu\""},"thomas":{"sw":"\"Pacha\""},"abraham":{"sw":"“Baba wa mataifa mengi”"},"isaac":{"sw":"“Anacheka” / “atacheka”"},"jacob":{"sw":"“Aliyechukua nafasi”, “ashikaye kisigino”"},"moses":{"sw":"“Aliyetolewa majini” (kwa mapokeo)"},"solomon":{"sw":"“Amani” (kutoka shalom)"},"matthew":{"sw":"“Zawadi ya Yahweh”"},"adam":{"sw":"“Mtu; binadamu”, kutoka adamah “ardhi, udongo”"},"noah":{"sw":"“Pumziko, faraja”"},"gabriel":{"sw":"“Mungu ni nguvu yangu”"},"elijah":{"sw":"“Mungu wangu ni Yahweh”"},"sarah":{"sw":"“Binti mfalme, mwanamke mtukufu”"},"anna":{"sw":"“Neema, upendeleo”"},"elizabeth":{"sw":"“Mungu wangu ni kiapo”"},"omar":{"sw":"“Mwenye maisha marefu, anayestawi”"},"aisha":{"sw":"“Hai, mwenye uhai, anayestawi”"},"khadija":{"sw":"“Aliyezaliwa mapema, mtoto aliyezaliwa kabla ya wakati”"},"abdullah":{"sw":"“Mja wa Mungu”"},"hassan":{"sw":"\"Mwema, mzuri, mrembo\""},"husayn":{"sw":"\"Hasan mdogo\", \"yule mzuri mdogo\""},"zaynab":{"sw":"Mmea wa jangwani wenye harufu nzuri na maua"},"nicholas":{"sw":"\"Ushindi wa watu\""},"helen":{"sw":"Haijulikani kwa hakika — huenda \"mwenge, mngʼaavu\""},"catherine":{"sw":"Haijulikani kwa hakika — kwa etimolojia ya kienyeji huhusishwa na \"safi\""},"margaret":{"sw":"\"Lulu\""},"philip":{"sw":"\"Mpenzi wa farasi\""},"theodore":{"sw":"\"Zawadi ya Mungu\""},"anthony":{"sw":"Jina la ukoo la Kirumi lenye asili isiyo dhahiri, huenda ya Kietruska"},"julia":{"sw":"\"Kijana\"; hali ya kike ya jina la ukoo Iulius, linalohusiana na Jupita"},"lakshmi":{"sw":"\"Alama, ishara\" → \"bahati njema, ustawi\""},"arjun":{"sw":"\"Angavu, nyeupe, fedha, safi\""},"sita":{"sw":"\"Mfuo wa jembe\" (mstari uliochorwa na plau)"},"ganesh":{"sw":"\"Bwana wa gana (makundi, majeshi)\""},"priya":{"sw":"\"Mpendwa, kipenzi\""}};
    var B = {"john":{"sw":"Mojawapo ya majina yaliyoenea zaidi Duniani. Jina la Kiebrania Yōḥānān, lililobebwa na John the Baptist na John the Apostle, liliingia katika Kigiriki kama Iōánnēs na Kilatini kama Iohannes, kisha likaenea katika ulimwengu wote wa Kikristo. Ulaya ya Magharibi ilihifadhi sauti ya awali J/G (John, Jean, Juan, Giovanni); ulimwengu wa Waslavu wa Mashariki uliligeuza kuwa Ivan; na Qurʼan huhifadhi umbo sambamba la Kiarabu, Yaḥyā, kwa nabii yuleyule."},"mary":{"sw":"Jina la mama wa Yesu na la Miriam dada wa Musa, na kupitia kwao likawa mojawapo ya majina ya wanawake yanayoheshimika zaidi ulimwenguni. Maria ya Kigiriki na Kilatini ilieneza jina hilo katika kila lugha ya Kikristo; Qurʼan hutoa Maryam, mwanamke pekee anayetajwa kwa jina ndani yake, hivyo jina hili ni muhimu vivyo hivyo katika ulimwengu wa Kiislamu."},"muhammad":{"sw":"Jina la Mtume wa Uislamu, na kwa mujibu wa mahesabu mengi ni jina la kiume linalojulikana zaidi Duniani. Kutoka Kiarabu muḥammad (mzizi ḥ-m-d, “kusifu”) lilisafiri pamoja na Uislamu hadi kila lugha ya ulimwengu wa Kiislamu, kila moja ikibadilisha sauti zake: Mehmet kwa Kituruki, Mohammad kwa Kiajemi/Kiurdu, Muhamed kwa Kibosnia, Mamadou Afrika Magharibi, Muhammad/Mohd Kusini-Mashariki mwa Asia."},"alexander":{"sw":"Alilibeba katika mabara matatu Alexander Mkuu, ambaye ushindi wake ulipanda jina hili kutoka Ugiriki hadi India. Baadaye Ukristo ulilieneza zaidi kupitia watakatifu na mapapa. Karibu kila mahali hufupishwa kwa mapenzi — Alex, Sasha, Sander, Xander, Ale, Iskandar — na hata liliingia katika ulimwengu wa Kiislamu kama Iskandar/Sikandar."},"joseph":{"sw":"Jina la baba wa ukoo Joseph, aliyeuzwa hadi Misri, na la Mtakatifu Joseph, mume wa Mary. Kiebrania Yōsēf kilipita katika Kigiriki Iōsḗph na Kilatini Ioseph hadi kila lugha ya Kikristo, kikifupishwa kuwa José katika Iberia, Giuseppe nchini Italia, na Josef katika ulimwengu wa Kijerumani na Kislavi. Qurʼan husimulia hadithi ya baba yuleyule wa ukoo kwa umbo sambamba la Kiarabu Yūsuf, lililoenea pamoja na Uislamu kutoka Afrika Magharibi hadi Indonesia."},"michael":{"sw":"Awali ni jina la malaika mkuu Michael, kiongozi shujaa wa jeshi la mbinguni, ambaye ibada yake ilibeba jina hili kote katika ulimwengu wa Kikristo. Michaḗl ya Kigiriki na Michael ya Kilatini zilijitawanya kuwa Michel, Miguel, Michele, Michael na Mikhail ya Kislavi, zikilainisha sauti ya kooni ya Kiebrania ḵ kuwa sauti ya k au h njiani. Qurʼani inamwita malaika huyo huyo Mīkāʼīl, ikitoa umbo la Kiislamu sambamba linalotumika kutoka Iran hadi Afrika Magharibi."},"george":{"sw":"Kutoka Kigiriki Geōrgios, lililojengwa juu ya geōrgós “mkulima, mlimaji wa ardhi”, jina hili linadaiwa kuenea kwake kukubwa kwa Saint George, shahidi muuaji-joka anayeheshimiwa kote katika ulimwengu wa Kikristo na mtakatifu mlinzi wa Uingereza, Georgia na Ethiopia. Linatanda kuwa Jorge, Giorgio, Georg na Jerzy, na ulimwengu wa Kislavi wa Mashariki uligawa jina hilo kuwa majina mawili yanayoishi — Georgy la kisomi na Yuri la kila siku. Katika Kaukasi ni kipenzi cha taifa: Giorgi wa Kigeorgia na Gevorg wa Kiarmenia."},"sophia":{"sw":"Kwa Kigiriki sophía humaanisha tu “hekima”, iliyofanywa mtu kama fadhila na kuenziwa katika kanisa kuu la Hagia Sophia mjini Constantinople, “Hekima Takatifu”. Likibebwa kupitia mapokeo ya Kibizantini na Kiothodoksi na kubebwa na wafalme-wanawake na watakatifu, jina hili lilienea kuwa Sofia, Sophie, Zsófia na Zofia. Leo ni miongoni mwa majina maarufu zaidi ya wasichana duniani, likiongoza chati za kuzaliwa kote Ulaya na bara la Amerika; Kirusi humpa umbo la kibembelezi lenye upendo Sonya."},"fatima":{"sw":"Ni jina la Fāṭima al-Zahrāʼ, binti wa Mtume Muhammad na mke wa ʿAlī, na hivyo ni miongoni mwa majina ya wanawake yanayoheshimiwa zaidi katika Uislamu — hasa katika mapokeo ya Kishia, ambako yeye ni mama wa maimamu. Kutoka shina la Kiarabu f-ṭ-m (“kuachisha kunyonya”), jina lilienea pamoja na Uislamu na kulainika njiani: Kituruki hukifupisha kuwa Fatma, Kiajemi huviringisha mwisho wake kuwa Fāṭeme, na Asia Kusini na Kusini-Mashariki huhifadhi umbo kamilifu zaidi Fatimah. Katika Balkan linaendelea kuishi kama Fatima pamoja na umbo la kipenzi Fata."},"ali":{"sw":"Ni jina la ʿAlī ibn Abī Ṭālib, binamu na mkwe wa Mtume Muhammad, khalifa wa nne katika mapokeo ya Kisuni na imamu wa kwanza wa Uislamu wa Kishia — jambo linalofanya Ali kuwa miongoni mwa majina makuu ya ulimwengu wa Kiislamu, na pia mojawapo ya “majina mazuri”, kwa kuwa al-ʿAlī ni sifa mojawapo ya Mungu. Kutoka Kiarabu ʿAlī (shina ʿ-l-w, “kuwa juu”), sauti zake husafiri kati ya lugha bila kubadilika sana: Ali ya Kituruki na Kiajemi, Ali ya Kiurdu, Alija ya Kibosnia, Aliyu ya Afrika Magharibi. Katika nchi za Magharibi anajulikana zaidi kupitia bondia Muhammad Ali."},"krishna":{"sw":"Krishna ni avatara wa nane wa Vishnu na mmoja wa miungu wanaopendwa zaidi katika Uhindu — mchunga ngʼombe apigaye filimbi wa Vrindavan na mwanazuoni mwendesha gari la farasi katika Bhagavad Gita. Neno la Kisanskriti kṛṣṇa kwa maana halisi lina maana ya \"giza, jeusi\", likieleza rangi ya ngozi yake, na limezaa maumbo ya kupendeza kama Kanha na Kannan ya Kitamil. Kama jina la kupewa, ni la kawaida kotekote nchini India na katika ughaibuni wote wa Kihindu; kuenea kwake Kusini-mashariki mwa Asia kulipitia tamthilia ya vivuli ya wayang na Mahabharata."},"rama":{"sw":"Rama ni avatara wa Vishnu na shujaa wa Ramayana, mfalme bora wa Ayodhya ambaye hadithi yake ni miongoni mwa zinazosimuliwa upya zaidi duniani. Neno la Kisanskriti rāma lina maana ya \"-a kupendeza, -a kuvutia\". Zaidi ya yote, ni utenzi huu uliobeba jina hilo kote Kusini-mashariki mwa Asia: wafalme wa Thailand wa nasaba ya Chakri wote huchukua jina la utawala la Rama, Ayutthaya yenyewe iliitwa kwa jina la Ayodhya mahali alikozaliwa Rama, na Rama bado hai katika Reamker ya Kambodia (kama Preah Ream), katika wayang ya Java na Bali, na katika Phra Lak Phra Ram ya Laos."},"david":{"sw":"Jina la mfalme-mchungaji wa Israeli, mfalme wa pili na muuaji wa Goliathi, anayeheshimiwa katika Uyahudi, Ukristo na Uislamu vilevile. Neno la Kiebrania Dāwīḏ lilipita katika Kigiriki na Kilatini likaingia katika kila lugha ya Ulaya bila kubadilika sana, huku Davit ya Kijojia na Dawit ya Kiethiopia zikiwa majina ya kifalme yenyewe. Kwa sababu Daudi pia ni nabii katika Qurʼani, mkondo sambamba wa Kiislamu unapita katika umbo la Kiarabu Dāwūd — Daud, Davut, Daudi — kotekote katika ulimwengu wa Kiislamu."},"daniel":{"sw":"Latokana na nabii mwenye maono katika Kitabu cha Danieli, ambaye imani yake ndani ya tundu la simba ilifanya jina hilo kuwa kielelezo cha uthabiti. Neno la Kiebrania Dāniyyēl lilisafiri kupitia Kigiriki Daniḗl na Kilatini Daniel hadi Magharibi ya Kikristo, likibaki thabiti kwa namna ya kushangaza katika tahajia, huku ulimwengu wa Kislavo ukiliumba upya kuwa Daniil na Danylo. Danieli pia anaheshimiwa katika mapokeo ya Kiislamu kama nabii Dāniyāl, ambaye kaburi lake huko Susa bado ni mahali pa hija."},"peter":{"sw":"Jina alilompa Yesu mvuvi Simoni — Kigiriki Pétros, \"mwamba\", tafsiri ya jina la utani la Kiaramu Kēfā — likimfanya kuwa mwamba ambao juu yake Kanisa lilijengwa. Akiwa papa wa kwanza, Mtakatifu Petro alilipeleka jina hilo katika kila nchi ya Kikristo: Kilatini Petrus, Kifaransa Pierre, Kihispania Pedro, Kiitaliano Pietro, Kirusi Pyotr. Wakristo wa Mashariki walibaki na Petros ya Kigiriki, na Wakristo wanaozungumza Kiarabu husema Buṭrus."},"paul":{"sw":"Jina la ukoo la Kirumi Paulus, lenye maana ya \"mdogo\", alilochukua Mtume Paul — aliyezaliwa akiitwa Saul wa Tarso — ambaye nyaraka zake ziliunda teolojia ya Kikristo na kubeba jina lake kotekote ulimwenguni. Makanisa yaliyozungumza Kigiriki yalimjua kama Paûlos, na kutoka Paulus ya Kilatini yakazuka Pablo, Paolo, Paulo, Paweł na Pavel ya Kislavoni. Kiarmenia kililibadilisha kwa namna ya kuvutia kuwa Poġos, nao Wakristo wanaozungumza Kiarabu humwita Būlus."},"thomas":{"sw":"Jina la utani la mtume aliyetilia shaka Ufufuo hadi alipogusa vidonda vya Kristo — Kiaramu Tʼōmā, “pacha”, ambalo Injili za Kigiriki pia hulitafsiri kama Dídymos. Kupitia Thōmâs ya Kigiriki na Thomas ya Kilatini, lilienea magharibi kama Thomas, Tomás, Tommaso na Tomasz, huku mashariki ya Kislavoni ikilibadilisha kuwa Foma na Khoma. Wakristo wanaozungumza Kiarabu huhifadhi sauti ya Kiaramu kama Tūmā."},"abraham":{"sw":"Baba wa mababu anayeheshimiwa kama baba wa waumini katika dini zote tatu za Kiibrahimu. Jina la Kiebrania Avraham, “baba wa mataifa mengi”, lilipita kupitia Abraám ya Kigiriki na Abraham ya Kilatini hadi Magharibi ya Kikristo, huku Qurʼani ikitoa umbo sambamba Ibrāhīm — mojawapo ya majina ya wanaume yanayojulikana zaidi katika ulimwengu wote wa Kiislamu, kuanzia Moroko hadi Indonesia. Kiholanzi hulifupisha kuwa Bram; eneo la Kaukasi hulibadilisha kuwa Ibragim."},"isaac":{"sw":"Mwana wa Abraham na baba wa mababu wa pili, jina lake la Kiebrania Yitzḥaq lenye maana ya “yeye hucheka.” Isaák ya Kigiriki na Isaac ya Kilatini zililibeba magharibi — Isacco ya Kiitaliano, Isaak ya Kijerumani na Kirusi — huku Qurʼani ikimwita nabii yuleyule Isḥāq. Likiwa jina pendwa miongoni mwa familia za Kiyahudi, Kikristo na Kiislamu vilevile, limebebwa na watu mashuhuri kuanzia Isaac Newton hadi mwandishi wa Kirusi Isaak Babel."},"jacob":{"sw":"Baba wa mababu wa tatu, aliyepewa jina jipya baadaye kuwa Israeli; jina lake la Kiebrania Yaʿaqov lilizua mojawapo ya miti ya ukoo iliyochanganyika zaidi katika elimu nzima ya majina. Kilatini Iacobus kilizaa Jacob, Jakob na Yakov ya Kislavoni, lakini kibadala cha Kilatini cha watu wa kawaida, Iacomus, kilijitenga na kuwa Giacomo ya Kiitaliano, Jacques ya Kifaransa, James ya Kiingereza, na Diego, Santiago, Tiago na Jaime za Iberia — vyote ni maumbo pacha ya jina lilelile moja. Qurʼani huhifadhi nabii huyu kama Yaʻqūb."},"moses":{"sw":"Nabii aliyewaongoza Waisraeli kutoka Misri; jina lake la Kiebrania Mosheh kwa jadi hufasiriwa kama \"aliyetolewa majini.\" Kupitia Kiyunani Mōÿsês na Kilatini Moyses, jina hilo lilienea kama Moses, Moïse kwa Kifaransa, Moisés kwa Kihispania na Mosè kwa Kiitaliano, huku Mūsā — anayetajwa katika Qurʼani mara nyingi kuliko nabii yeyote mwingine — akawa mojawapo ya majina makuu ya ulimwengu wa Kiislamu, lililobebwa na mfalme wa Mali Mansa Musa."},"solomon":{"sw":"Mfalme mwenye hekima, mwana wa David; jina lake la Kiebrania Shlomoh latokana na shalom, yaani \"amani.\" Kiyunani Solomṓn na Kilatini Salomon vilizaa Solomon, Salomon kwa Kifaransa, Salomone kwa Kiitaliano na Salomão kwa Kireno. Watawala wa Ethiopia walidai kuwa wazao wake katika ukoo wa Solomon, na Qurʼani inamheshimu kama nabii-mfalme Sulaymān — chanzo cha jina la Kituruki Süleyman, lililobebwa na mkuu kuliko masultani wote wa Milki ya Othmaniyya."},"matthew":{"sw":"Jina la mtume na mwinjilisti Matthew, mtoza ushuru aliyeitwa na Yesu na kwa jadi mwandishi wa Injili ya kwanza. Kiebrania Mattityāhū (\"zawadi ya Yahweh\") kilifupishwa katika Kiyunani kuwa Maththaîos na kufanywa cha Kilatini kama Matthaeus, kisha kikaenea katika ulimwengu wote wa Kikristo kama Matteo, Mateo, Matthieu, Mateusz na Matvei wa lugha za Kislavoni. Wakristo wanaozungumza Kiarabu wanamfahamu mwinjilisti huyu kama Mattā."},"adam":{"sw":"Jina la mtu wa kwanza, aliyeumbwa kutoka udongo katika Kitabu cha Mwanzo na kutajwa mara ishirini na tano katika Qurʼani, hivyo linashirikiwa na Wayahudi, Wakristo na Waislamu sawasawa. Jambo lisilo la kawaida, halihitaji kubadilishwa umbo kutoka lugha moja hadi nyingine — Adam katika Kiingereza, Kijerumani, Kipolandi na Kiarabu, Adán kwa Kihispania, Adamo kwa Kiitaliano, Adem kwa Kituruki na Kibosnia, Adamu kwa Kihausa na Kiswahili. Katika ulimwengu wa Kiislamu, Ādam ni jina la kawaida sana la kila siku."},"noah":{"sw":"Mjenzi wa safina aliyenusurika Gharika, anayeheshimiwa katika Biblia na Qurʼani sawasawa. Kiebrania Nōaḥ kilipita katika Kiyunani Nôe na Kilatini Noe hadi kuwa Noé katika lugha za Kiromance na Noè kwa Kiitaliano, huku Kiingereza kikihifadhi umbo kamili zaidi Noah. Katika karne ya ishirini na moja, Noah limepaa hadi kileleni mwa orodha za majina ya wavulana kote Marekani na Ulaya, na hata limekopwa upya nchini Japani kama jina la kisasa Noa. Qurʼani inasimulia hadithi ile ile kwa umbo sambamba la Kiarabu Nūḥ, mmoja wa mitume watano wakuu zaidi wa Uislamu."},"gabriel":{"sw":"Jina la malaika mkuu anayemfunulia Daniel maono, akitangaza kuzaliwa kwa John na Jesus, na ambaye katika Uislamu humfunulia Muhammad Qurʼan. Neno la Kiebrania Gaḇrīʼēl likawa Gabriḗl la Kigiriki na Gabriel la Kilatini, likibaki karibu na asili yake katika Kifaransa, Kihispania, Kireno na Kijerumani, likilainika kuwa Gabriele wa Kiitaliano na Gavriil / Gavrilo wa Kislavi. Qurʼan humwita malaika huyohuyo Jibrīl, na nchini Ethiopia malaika mkuu Gabrʼel anaheshimiwa sana."},"elijah":{"sw":"Jina la nabii mkali wa karne ya tisa KK aliyekabiliana na makuhani wa Baal mlimani Carmel na akapaishwa mbinguni katika kimbunga. Katika Kiyunani cha Agano Jipya yeye ni Ēlías, iliyozaa Elias wa Kilatini na maumbo mengi ya Ulaya Elias / Élie / Ilie, huku ulimwengu wa Kislavi cha Mashariki ukimfanya kuwa Ilya wa kila siku. Umbo kamili zaidi Elijah umekuwa mojawapo ya majina maarufu zaidi ya Kiingereza cha kisasa. Qurʼan humheshimu nabii huyohuyo kwa umbo la Kiarabu sambamba Ilyās."},"sarah":{"sw":"Jina la mke wa baba wa mababu Abraham, ambaye katika Mwanzo anabadilishwa jina kutoka Sarai kuwa Sarah, \"binti mfalme\". Sárra wa Kiyunani na Sara wa Kilatini vililieneza katika ulimwengu wote wa Kikristo, ambako likawa mojawapo ya majina maarufu zaidi ya wanawake katika enzi ya kisasa. Kwa kuwa Abraham ni baba wa mababu wa pamoja, jina hilohilo linaendelea kuishi katika ulimwengu wa Kiislamu kama Sāra, nalo hubadilika kwa upendo kutoka Zara hadi Saara wa Kifini."},"anna":{"sw":"Kutoka Kiebrania Ḥannāh, mama wa nabii Samuel, jina lenye maana ya \"neema\". Kiyunani kiliiandika Ánna — jina alilobeba nabii wa kike Anna katika Injili ya Luka — na kupitia Kilatini likawa mojawapo ya majina ya wanawake yaliyoenea zaidi barani Ulaya, likiheshimiwa zaidi kama jina la mtakatifu Anne, mama wa Bikira Mary. Kiingereza huhifadhi Anna lenye asili ya Kiyunani na Hannah lililorejeshwa kutoka Kiebrania kama jozi, na mtu huyohuyo hutokea katika Uislamu kama Ḥanna, mama wa Mary."},"elizabeth":{"sw":"Kutoka Kiebrania Elišévaʿ, mke wa Aaron na, katika Injili ya Luka, mama wa John Mbatizaji. Elisábet wa Kiyunani na Elisabeth wa Kilatini vilieneza jina hilo katika ulimwengu wote wa Kikristo, ambako lilibebwa na watakatifu na msururu mrefu wa malkia, hasa Elizabeth I na Elizabeth II wa Uingereza. Katika Rasi ya Iberia jina hilohilo liliundwa upya kuwa tawi maarufu, Isabel (Kiitaliano Isabella), huku ulimwengu wa Kislavi na wa Kihungaria ukilipa Yelizaveta na Erzsébet."},"omar":{"sw":"Jina hili lilibebwa na ʿUmar ibn al-Khattāb, sahaba wa Mtume na khalifa wa pili wa Rāshidūn ambaye utawala wake uliunda dola ya awali ya Kiislamu; ʿUmar ni mojawapo ya majina ya kawaida ya wanaume katika ulimwengu wa Kiislamu. Kutoka mzizi wa Kiarabu ʿ-m-r (“kuishi, kusitawi”) lina maana ya “mwenye kuishi muda mrefu, anayestawi”. Lilibadilika kuwa Ömer ya Kituruki na Omer ya Kibosnia, na likafika Magharibi kupitia watu kama Omar Sharif. Jina la Kiebrania lisilohusiana, Omar — mjukuu wa Esau katika kitabu cha Mwanzo — ni sadfa tu ya kifonetiki iliyo tofauti."},"aisha":{"sw":"Ni jina la ʿĀʼisha bint Abī Bakr, mke wa Mtume Muhammad aliyejulikana kama msomi na mpokezi wa hadithi, jambo lililolifanya kuwa mojawapo ya majina ya wanawake yanayopendwa zaidi katika ulimwengu wote wa Kiislamu. Kutoka mzizi wa Kiarabu ʿ-y-sh (“kuishi”) lina maana ya “aliye hai”. Kituruki kililibadilisha kuwa Ayşe — kwa muda mrefu jina la mwanamke lililo la kawaida zaidi nchini Uturuki — huku Maghrebi ikitumia Aïcha na Asia Kusini Ayesha. Katika miongo ya hivi karibuni limeenea sana pia nchini Uingereza, Ufaransa na Marekani."},"khadija":{"sw":"Khadīja bint Khuwaylid alikuwa mke wa kwanza wa Mtume Muhammad, mfanyabiashara tajiri wa Makka na mtu wa kwanza kuukubali Uislamu; tangu wakati huo jina lake limethaminiwa. Linatokana na mzizi wa Kiarabu kh-d-j, unaohusiana na mtoto “aliyezaliwa mapema” au kabla ya wakati. Kituruki hulibeba kama Hatice, Afrika Magharibi kama Hadiza ya Kihausa na Khady ya Kisenegali, na Kiswahili kama Hadija. Pamoja na Fatima na Aisha, ni miongoni mwa majina ya wanawake yaliyo ya kawaida zaidi katika ulimwengu wa Kiislamu."},"abdullah":{"sw":"Ni jina la kitheofori lenye maana ya “mja wa Mungu”, lililoundwa kutoka ʿabd (“mja”) na Allāh. Lilikuwa jina la baba yake Mtume Muhammad, ʿAbd Allāh ibn ʿAbd al-Muttalib, na hadithi moja inataja ʿAbdullāh na ʿAbd al-Rahmān kuwa majina yanayopendwa zaidi na Mungu — hivyo ni miongoni mwa majina yanayopendekezwa zaidi katika Uislamu. Linaenea katika ulimwengu wa Kiislamu kwa mabadiliko madogo tu ya kifonetiki: Abdollah ya Kiajemi, Abdallah na Abdellah za Kimaghrebi, Abdullahi ya Kinigeria, Abdoulaye ya Afrika Magharibi inayozungumza Kifaransa, na Abdulah ya Kibosnia."},"hassan":{"sw":"Ḥasan (mzizi ḥ-s-n, “kuwa mwema, mzuri”) lilikuwa jina la Hasan ibn Ali, mjukuu mkubwa wa Mtume Muhammad na Imamu wa pili wa Kishia. Karibu daima huunganishwa na jina la ndugu yake mdogo — Hasan na Husayn pamoja. Likibebwa na Uislamu kote ulimwenguni, lilihifadhi umbo lililo thabiti kwa namna ya kushangaza (Hasan ya Kituruki, Hasan/Haso ya Kibosnia) na linabaki kuwa mojawapo ya majina ya wanaume yaliyo ya kawaida zaidi katika ulimwengu wa Kiislamu."},"husayn":{"sw":"Ḥusayn ni umbo dogo la Ḥasan — \"Hasan mdogo\", \"yule mzuri mdogo\". Lilibebwa na Husayn ibn Ali, mjukuu mdogo wa Mtume, ambaye kufa kwake shahidi katika Vita vya Karbala mwaka 680 BK kulifanya jina hili kuwa moyo wa kihisia wa Uislamu wa Kishia, likikumbukwa kila mwaka wakati wa Ashura. Maumbo yake huzunguka ulimwengu wa Kiislamu: Hossein la Kiajemi, Hüseyin la Kituruki, Hussain la Asia Kusini, na Hussein la Kiarabu lililobebwa na Saddam Hussein na Mfalme Hussein wa Yordani."},"zaynab":{"sw":"Zaynab ni jina la mmea wa jangwani wenye harufu nzuri unaotoa maua. Lilibebwa na binti wa Mtume Muhammad, Zaynab bint Muhammad, na mjukuu wake Zaynab bint Ali, dada yake Husayn na shujaa wa kike anayeheshimika katika msiba wa Karbala. Jina hili linastawi katika ulimwengu wote wa Kiislamu, hasa kama Zeynep la Kituruki — kwa miaka mingi jina la wasichana lililopendwa zaidi nchini Uturuki — na kama Zenabou la Afrika Magharibi."},"nicholas":{"sw":"Kutoka Kigiriki Nikólaos, \"ushindi wa watu\", lililoenea katika ulimwengu wa Kikristo kupitia ibada ya Mtakatifu Nicholas wa Myra — askofu wa karne ya 4 ambaye hekaya yake ya kutoa zawadi ikawa Santa Claus, jina ambalo lenyewe limemomonyoka kutoka Kiholanzi Sinterklaas. Karibu kila mahali hufupishwa kwa upendo: Klaus kwa Kijerumani, Klaas kwa Kiholanzi, Nikos kwa Kigiriki, Kolya kwa Kirusi. Ulaya Mashariki ililiumba upya kuwa Nikolai, Mykola na Mikuláš, huku Hungaria ikilifanya Miklós."},"helen":{"sw":"Umbo la Kiingereza la Helénē ya Kigiriki, yaelekea kutoka neno lenye maana ya \"mwenge\" au \"mngʼaavu\". Lilibebwa na Helen wa Troya, ambaye uzuri wake ilisemekana \"ulizindua meli elfu\", na na Mtakatifu Helena, mama wa Kaisari Constantine, anayehesabiwa kuwa aligundua Msalaba wa Kweli. Kupitia Kilatini Helena likawa Elena katika ulimwengu wa Kiromance na Kislavu cha kusini, na Yelena / Olena upande wa mashariki, huku Kihungaria kikiliumba upya kuwa Ilona."},"catherine":{"sw":"Kutoka Kigiriki Aikaterínē, ambalo mapema lilihusishwa kwa etimolojia ya kienyeji na katharós, \"safi\", jambo lililoimarisha tahajia ya -th- huko Magharibi. Likienea kwa ibada iliyopendwa mno ya Mtakatifu Catherine wa Aleksandria, likawa mojawapo ya majina ya wanawake yaliyotumika zaidi barani Ulaya, likibebwa na malkia na maliki wa kike kutoka Catherine de Medici hadi Catherine the Great. Hufupishwa kuwa kabati zima la majina ya kubembeleza — Kate, Katie, Katya, Kasia — mojawapo, yaani Karin la Kijerumani na Kiswidi, hutamkwa sawa na jina la msichana wa Kijapani."},"margaret":{"sw":"Kutoka neno la Kigiriki margarítēs (\"lulu\"), neno ambalo Kigiriki chenyewe kilikopa kutoka mashariki ya mbali zaidi. Ibada ya Mtakatifu Margaret wa Antiokia ilikifanya kipendwe kote Ulaya ya zama za kati, baadaye kikabebwa na malkia na watu mashuhuri kuanzia Margaret Thatcher hadi Margaret Atwood. Majina ya kubembeleza yalijipatia uhai wao — Greta la Kijerumani, Rita la Kiitaliano na Kihispania, na Daisy la Kiingereza, kwa kuwa neno la Kifaransa marguerite baadaye likawa jina la ua hilo."},"philip":{"sw":"Kutoka neno la Kigiriki Phílippos (\"mpenzi wa farasi\"), jina la ufalme wa Makedonia lililobebwa na Philip II, baba yake Alexander Mkuu. Kama jina la mtume mmoja lilienea katika ulimwengu wa Kikristo, na likawa kipenzi cha wafalme wa Iberia — Felipe sita wa Uhispania na Filipe kadhaa wa Ureno, ambao visiwa vya Ufilipino (Philippines) vimeitwa kwa jina lao. Waingereza wanalifahamu zaidi kupitia Prince Philip, marehemu Duke wa Edinburgh."},"theodore":{"sw":"Kutoka neno la Kigiriki Theódōros (\"zawadi ya Mungu\"), taswira iliyogeuzwa ya Dorothea. Likibebwa na watakatifu wengi wa mwanzo, lilishika mizizi kote Ulaya na kwingineko — Fyodor la Kirusi la Dostoevsky na Tewodros la Ethiopia. Katika Kiingereza, huvutia kupitia majina ya kubembeleza Ted, Teddy na Theo."},"anthony":{"sw":"Kutoka jina la ukoo la Kirumi Antōnius, gens ya kale ambayo huenda ilikuwa na asili ya Kietruska na ambayo mwanachama wake mwenye sifa mbaya zaidi alikuwa Mark Antony (Marcus Antōnius). Watakatifu wengi walioitwa Anthony — hasa Anthony Mkuu na Anthony wa Padua — walilibeba katika ulimwengu wa Kikristo, ambako Antonio likawa mojawapo ya majina yanayojulikana zaidi nchini Italia na Iberia. Tahajia yenye herufi h inaonyesha uhusiano wa baadaye na wenye makosa na neno la Kigiriki ánthos (\"ua\")."},"julia":{"sw":"Umbo la kike la jina la gens ya Kirumi Iūlius, familia ya Julius Caesar na Maliki Augustus, jambo lililofanya Iūlia kuwa mojawapo ya majina makuu ya nasaba ya Julio-Claudius — binti wa Caesar na binti wa Augustus wote waliitwa Julia. Kwa muda mrefu pia lilikuwa jina la mtakatifu wa Kikristo, na leo ni mojawapo ya majina ya wasichana yanayopendwa zaidi kote Ulaya na bara la Amerika. Umbo lake la kiume linaendelea kuishi kama Julius, Julio na Jules."},"lakshmi":{"sw":"Lakshmi ni mungu wa kike wa Kihindu wa mali, bahati na urembo, na mke wa Vishnu, ambaye hujitokeza kando ya kila mojawapo ya avatara zake kwa umbo linalolingana. Neno la Kisanskrit lakṣmī latokana na lakṣ \"kutia alama, kutambua\", likileta maana ya ishara njema na, kwa kupanuka, ustawi. Anaabudiwa zaidi ya yote wakati wa Diwali, na jina lake ni mojawapo ya majina ya wanawake yanayojulikana zaidi kote kusini mwa India — ingawa majina ya mchanganyiko kama Lakshmi Narayan na majina ya ukoo kama Mittal huwabeba wanaume pia. Huko Bengal, mungu huyo wa kike pamoja na jina hutamkwa Lokkhi."},"arjun":{"sw":"Arjuna ni shujaa-mpiga-mishale wa Mahabharata — wa tatu miongoni mwa ndugu watano wa Pandava, mwana wa mungu Indra, na yule shujaa ambaye Krishna anamkabidhi Bhagavad Gita katika uwanja wa vita wa Kurukshetra. Neno la Kisanskrit arjuna maana yake \"-enye kungʼaa, -a fedha, -eupe\". Katika umbo la Arjun, ni mojawapo ya majina ya wavulana yanayopendwa zaidi katika India ya leo, na tenzi hiyo ilieneza mhusika huyu kote Kusini-mashariki mwa Asia, ambako ksatriya mstaarabu Arjuna (kwa Kijava Janaka) ni kipenzi cha maonyesho ya vivuli ya wayang."},"sita":{"sw":"Sita ni shujaa wa kike wa Ramayana na mke wa Rama, avatara wa Lakshmi na kielelezo kamili cha wema, ujitoaji na uaminifu. Jina lake la Kisanskrit maana yake \"mtaro wa jembe\": alipatikana na Mfalme Janaka katika shamba lililolimwa, binti wa mungu wa kike wa ardhi Bhumi. Tenzi hiyo ilimueneza kote Kusini-mashariki mwa Asia — yeye ni Nang Sida (นางสีดา) katika Ramakien ya Thailand, Sinta au Shinta katika wayang ya Kijava, na Neang Seda katika Reamker ya Kambodia."},"ganesh":{"sw":"Ganesha ni mwana mwenye kichwa cha tembo wa Shiva na Parvati, mungu mpendwa aondoaye vipingamizi na mlinzi wa mianzo, elimu na sanaa, aombwaye kabla ya kila jambo jipya. Jina lake la Kisanskrit huchanganya gaṇa “makundi, majeshi” na īśa “bwana”, naye pia hujulikana kama Vinayaka na Ganapati. Katika umbo la Ganesh, ni jina la kawaida la wavulana nchini India, na mungu huyu alienea kote Kusini-mashariki mwa Asia — akiabudiwa Thailand kama Phra Phikhanet (พระพิฆเนศ), mlinzi wa sanaa, na Indonesia kama Ganesha, ambaye sura yake ni nembo ya Taasisi ya Teknolojia ya Bandung (ITB)."},"priya":{"sw":"Priya si jina la mungu bali ni jina la mtu tu — umbo la kike la neno la Kisanskrit priya “mpendwa, kipenzi”, kutoka shina prī “kupendeza”. Ni mojawapo ya majina ya wanawake yanayojulikana zaidi leo kote India, Nepal, Bangladesh na Sri Lanka, nalo huingia kwa urahisi katika jamii za ughaibuni likiwa umbo la kirafiki na rahisi kutamka. Katika Kitamil, umbo la kiume Priyan au Priya hutumika kwa wanaume pia. Shina hili ni la kale: lina uhusiano wa asili na jina la mungu wa kike wa Kijerumani Frigg, yote mawili yatokana na Kihindi-Ulaya cha Awali *priH- “mpendwa”."}};
